insert into island_sentences (word, sentence, reading, english, wrong) values
  ('教室', '同学们都坐在＿＿里听老师讲故事。', 'Tóngxuémen dōu zuò zài jiàoshì lǐ tīng lǎoshī jiǎng gùshi.', 'The pupils all sit in the classroom to hear the teacher''s story.', array['作业','书包']::text[]),
  ('作业', '回家以后，我要先做＿＿再玩。', 'Huí jiā yǐhòu, wǒ yào xiān zuò zuòyè zài wán.', 'After getting home I do my homework before playing.', array['教室','书包']::text[]),
  ('书包', '他的＿＿里有课本和铅笔。', 'Tā de shūbāo lǐ yǒu kèběn hé qiānbǐ.', 'His school bag has textbooks and pencils in it.', array['作业','考试']::text[]),
  ('同学', '下课后，我和＿＿一起玩。', 'Xiàkè hòu, wǒ hé tóngxué yìqǐ wán.', 'After class I play with my classmates.', array['作业','书包']::text[]),
  ('考试', '明天有数学＿＿，我今晚要复习。', 'Míngtiān yǒu shùxué kǎoshì, wǒ jīnwǎn yào fùxí.', 'There is a maths exam tomorrow, so I must revise tonight.', array['黑板','铅笔']::text[]),
  ('课本', '请把＿＿翻到第十页。', 'Qǐng bǎ kèběn fān dào dì shí yè.', 'Please turn your textbook to page ten.', array['考试','教室']::text[]),
  ('铅笔', '我用＿＿写字，写错了可以擦掉。', 'Wǒ yòng qiānbǐ xiě zì, xiě cuò le kěyǐ cā diào.', 'I write with a pencil, so I can rub out mistakes.', array['黑板','作业']::text[]),
  ('黑板', '老师在＿＿上写了今天的题目。', 'Lǎoshī zài hēibǎn shàng xiě le jīntiān de tímù.', 'The teacher wrote today''s topic on the blackboard.', array['同学','考试']::text[]),
  ('志愿者', '我是社区中心的＿＿，每个星期六都来帮忙。', 'Wǒ shì shèqū zhōngxīn de zhìyuànzhě, měi gè xīngqīliù dōu lái bāngmáng.', 'I am a volunteer at the community centre and help out every Saturday.', array['报名','课程']::text[]),
  ('报名', '想参加书法班的人，请到前台＿＿。', 'Xiǎng cānjiā shūfǎ bān de rén, qǐng dào qiántái bàomíng.', 'If you want to join the calligraphy class, please sign up at the front desk.', array['欢迎','志愿者']::text[]),
  ('课程', '这个＿＿教老人怎么用手机。', 'Zhège kèchéng jiāo lǎorén zěnme yòng shǒujī.', 'This course teaches the elderly how to use a phone.', array['报名','欢迎']::text[]),
  ('欢迎', '阿姨笑着说：“＿＿来到我们的俱乐部！”', 'Āyí xiàozhe shuō: “Huānyíng lái dào wǒmen de jùlèbù!”', 'The auntie smiled and said, “Welcome to our club!”', array['课程','志愿者']::text[]),
  ('书法', '每个星期六，爷爷都去会馆练习＿＿。', 'Měi gè xīngqīliù, yéye dōu qù huìguǎn liànxí shūfǎ.', 'Every Saturday Grandpa goes to the club to practise calligraphy.', array['志愿者','欢迎']::text[]),
  ('免费', '这个讲座是＿＿的，不用付钱。', 'Zhège jiǎngzuò shì miǎnfèi de, bú yòng fùqián.', 'This talk is free; you do not need to pay.', array['帮忙','书法']::text[]),
  ('帮忙', '邻居搬家，我们去＿＿搬箱子。', 'Línjū bānjiā, wǒmen qù bāngmáng bān xiāngzi.', 'The neighbour is moving house, so we go to help carry boxes.', array['免费','会员']::text[]),
