  ('警察', '迷路的人可以向＿＿求助。', 'Mílù de rén kěyǐ xiàng jǐngchá qiúzhù.', 'People who are lost can ask the police for help.', array['安全','巡逻']::text[]),
  ('安全', '晚上回家要小心，注意＿＿。', 'Wǎnshang huí jiā yào xiǎoxīn, zhùyì ānquán.', 'Be careful going home at night and mind your safety.', array['警察','报警']::text[]),
  ('巡逻', '警察每天晚上在社区里＿＿。', 'Jǐngchá měitiān wǎnshang zài shèqū lǐ xúnluó.', 'The police patrol the neighbourhood every night.', array['安全','报警']::text[]),
  ('报警', '看到可疑的人，要马上＿＿。', 'Kàndào kěyí de rén, yào mǎshàng bàojǐng.', 'If you see a suspicious person, call the police at once.', array['巡逻','安全']::text[]),
  ('迷路', '小朋友在商场里＿＿了，哭了起来。', 'Xiǎopéngyou zài shāngchǎng lǐ mílù le, kū le qǐlái.', 'The little child got lost in the mall and began to cry.', array['钱包','小偷']::text[]),
  ('小偷', '警察抓到了偷东西的＿＿。', 'Jǐngchá zhuādào le tōu dōngxi de xiǎotōu.', 'The police caught the thief who stole things.', array['迷路','提醒']::text[]),
  ('钱包', '我的＿＿不见了，里面有身份证。', 'Wǒ de qiánbāo bú jiàn le, lǐmiàn yǒu shēnfènzhèng.', 'My wallet is missing and my ID card is inside.', array['小偷','提醒']::text[]),
  ('提醒', '警察＿＿大家锁好门窗。', 'Jǐngchá tíxǐng dàjiā suǒ hǎo ménchuāng.', 'The police remind everyone to lock their doors and windows.', array['钱包','迷路']::text[]),
  ('老板', '＿＿，再给我一碗汤！', 'Lǎobǎn, zài gěi wǒ yì wǎn tāng!', 'Boss, another bowl of soup please!', array['米饭','酱油']::text[]),
  ('米饭', '这块鸡肉配上香喷喷的＿＿最好吃。', 'Zhè kuài jīròu pèi shàng xiāngpēnpēn de mǐfàn zuì hǎochī.', 'This chicken is best with fragrant rice.', array['酱油','汤']::text[]),
  ('酱油', '请在饭上淋一点＿＿。', 'Qǐng zài fàn shàng lín yìdiǎn jiàngyóu.', 'Please drizzle a little soy sauce on the rice.', array['汤','老板']::text[]),
  ('汤', '天气凉，我想喝一碗热＿＿。', 'Tiānqì liáng, wǒ xiǎng hē yì wǎn rè tāng.', 'It is cool, so I would like a bowl of hot soup.', array['米饭','酱油']::text[]),
  ('盘子', '请把鸡饭放在白色的＿＿里。', 'Qǐng bǎ jīfàn fàng zài báisè de pánzi lǐ.', 'Please put the chicken rice on the white plate.', array['酱油','黄瓜']::text[]),
