  ('车票', '我没有卡，所以买了一张＿＿。', 'Wǒ méiyǒu kǎ, suǒyǐ mǎi le yì zhāng chēpiào.', 'I have no card, so I bought a ticket.', array['延误','列车']::text[]),
  ('列车', '＿＿马上就要进站了。', 'Lièchē mǎshàng jiùyào jìn zhàn le.', 'The train is about to arrive at the station.', array['车票','延误']::text[]),
  ('延误', '信号故障，列车会＿＿十分钟。', 'Xìnhào gùzhàng, lièchē huì yánwù shí fēnzhōng.', 'There is a signal fault; the train will be delayed ten minutes.', array['车票','闸门']::text[]),
