  ('方向', '你坐错了＿＿，要到对面的月台。', 'Nǐ zuò cuò le fāngxiàng, yào dào duìmiàn de yuètái.', 'You took the wrong direction; go to the platform opposite.', array['广播','延误']::text[]),
  ('紧急', '遇到＿＿情况，请按红色的按钮。', 'Yùdào jǐnjí qíngkuàng, qǐng àn hóngsè de ànniǔ.', 'In an emergency, please press the red button.', array['车票','地图']::text[]),
  ('地图', '我看不懂路线，请给我一张＿＿。', 'Wǒ kàn bu dǒng lùxiàn, qǐng gěi wǒ yì zhāng dìtú.', 'I cannot understand the route; please give me a map.', array['闸门','方向']::text[]),
  ('扶手', '车开得快，请抓紧＿＿。', 'Chē kāi de kuài, qǐng zhuājǐn fúshǒu.', 'The bus is moving fast; please hold the handrail.', array['铃','终点站']::text[]),
