  ('让座', '看到老人上车，要主动＿＿。', 'Kàndào lǎorén shàngchē, yào zhǔdòng ràngzuò.', 'When you see an elderly person board, you should offer your seat.', array['车厢','扶手']::text[]),
  ('刹车', '前面有人过马路，司机马上＿＿。', 'Qiánmiàn yǒu rén guò mǎlù, sījī mǎshàng shāchē.', 'Someone was crossing the road ahead, so the driver braked at once.', array['车厢','扶手']::text[]),
  ('车厢', '这趟车的＿＿里很拥挤。', 'Zhè tàng chē de chēxiāng lǐ hěn yōngjǐ.', 'It is very crowded inside this carriage.', array['刹车','让座']::text[]),
  ('机场', '请载我去樟宜＿＿。', 'Qǐng zài wǒ qù Zhāngyí jīchǎng.', 'Please take me to Changi Airport.', array['地址','红灯']::text[]),
