  ('空车', '路边有一辆＿＿，我们快招手吧。', 'Lù biān yǒu yí liàng kōngchē, wǒmen kuài zhāoshǒu ba.', 'There is a free taxi by the road; let us wave quickly.', array['安全带','导航']::text[]),
  ('后座', '小孩要坐在＿＿，并且系好安全带。', 'Xiǎohái yào zuò zài hòuzuò, bìngqiě jì hǎo ānquándài.', 'Children must sit in the back seat and fasten the seat belt.', array['导航','找钱']::text[]),
  ('bilik darjah', 'Semua murid duduk di ＿＿ untuk mendengar cerita cikgu.', '', 'The pupils all sit in the classroom to hear the teacher''s story.', array['kerja rumah','beg sekolah']::text[]),
  ('kerja rumah', 'Selepas pulang, saya siapkan ＿＿ dahulu sebelum bermain.', '', 'After getting home I do my homework before playing.', array['bilik darjah','beg sekolah']::text[]),
  ('beg sekolah', 'Di dalam ＿＿ dia ada buku teks dan pensel.', '', 'His school bag has textbooks and pencils in it.', array['kerja rumah','peperiksaan']::text[]),
  ('rakan sekelas', 'Selepas kelas, saya bermain bersama ＿＿ saya.', '', 'After class I play with my classmates.', array['kerja rumah','beg sekolah']::text[]),
  ('peperiksaan', 'Esok ada ＿＿ matematik, jadi malam ini saya perlu mengulang kaji.', '', 'There is a maths exam tomorrow, so I must revise tonight.', array['papan hitam','pensel']::text[]),
  ('buku teks', 'Sila buka ＿＿ anda ke muka surat sepuluh.', '', 'Please turn your textbook to page ten.', array['peperiksaan','bilik darjah']::text[]),
  ('pensel', 'Saya menulis dengan ＿＿, jadi boleh dipadam kalau tersilap.', '', 'I write with a pencil, so I can rub out mistakes.', array['papan hitam','kerja rumah']::text[]),
  ('papan hitam', 'Cikgu menulis tajuk hari ini di atas ＿＿.', '', 'The teacher wrote today''s topic on the blackboard.', array['rakan sekelas','peperiksaan']::text[]),
  ('sukarelawan', 'Saya seorang ＿＿ di pusat komuniti dan membantu setiap hari Sabtu.', '', 'I am a volunteer at the community centre and help out every Saturday.', array['mendaftar','kursus']::text[]),
  ('mendaftar', 'Kalau mahu menyertai kelas kaligrafi, sila ＿＿ di kaunter depan.', '', 'If you want to join the calligraphy class, please sign up at the front desk.', array['selamat datang','sukarelawan']::text[]),
  ('kursus', '＿＿ ini mengajar warga emas cara menggunakan telefon.', '', 'This course teaches the elderly how to use a phone.', array['mendaftar','selamat datang']::text[]),
  ('selamat datang', 'Mak cik itu tersenyum dan berkata, “＿＿ ke kelab kami!”', '', 'The auntie smiled and said, “Welcome to our club!”', array['kursus','sukarelawan']::text[]),
  ('kaligrafi', 'Setiap hari Sabtu, datuk pergi ke kelab untuk berlatih ＿＿.', '', 'Every Saturday Grandpa goes to the club to practise calligraphy.', array['sukarelawan','selamat datang']::text[]),
  ('percuma', 'Ceramah ini ＿＿, tidak perlu membayar.', '', 'This talk is free; you do not need to pay.', array['tolong','kaligrafi']::text[]),
  ('tolong', 'Jiran kami berpindah rumah, jadi kami pergi ＿＿ mengangkat kotak.', '', 'The neighbour is moving house, so we go to help carry boxes.', array['percuma','ahli']::text[]),
  ('ahli', 'Dia ialah ＿＿ kelab itu dan boleh menyertai semua aktiviti.', '', 'He is a member of the club and can join all the activities.', array['kursus','tolong']::text[]),
  ('polis', 'Orang yang sesat boleh meminta bantuan ＿＿.', '', 'People who are lost can ask the police for help.', array['keselamatan','meronda']::text[]),
  ('keselamatan', 'Berhati-hati semasa pulang pada waktu malam dan jaga ＿＿ anda.', '', 'Be careful going home at night and mind your safety.', array['polis','lapor polis']::text[]),
  ('meronda', 'Polis ＿＿ kawasan kejiranan setiap malam.', '', 'The police patrol the neighbourhood every night.', array['keselamatan','lapor polis']::text[]),
  ('lapor polis', 'Jika anda nampak orang yang mencurigakan, ＿＿ dengan segera.', '', 'If you see a suspicious person, call the police at once.', array['meronda','keselamatan']::text[]),
  ('sesat', 'Kanak-kanak kecil itu ＿＿ di pusat membeli-belah lalu menangis.', '', 'The little child got lost in the mall and began to cry.', array['dompet','pencuri']::text[]),
  ('pencuri', 'Polis menangkap ＿＿ yang mencuri barang.', '', 'The police caught the thief who stole things.', array['sesat','mengingatkan']::text[]),
  ('dompet', '＿＿ saya hilang dan kad pengenalan saya ada di dalamnya.', '', 'My wallet is missing and my ID card is inside.', array['pencuri','mengingatkan']::text[]),
  ('mengingatkan', 'Polis ＿＿ semua orang supaya mengunci pintu dan tingkap.', '', 'The police remind everyone to lock their doors and windows.', array['dompet','sesat']::text[]),
  ('bos', '＿＿, tambah semangkuk sup lagi, ya!', '', 'Boss, another bowl of soup please!', array['pinggan','kicap']::text[]),
  ('kicap', 'Sila tuang sedikit ＿＿ di atas nasi.', '', 'Please drizzle a little soy sauce on the rice.', array['sup','bos']::text[]),
  ('sup', 'Cuaca sejuk, jadi saya mahu semangkuk ＿＿ panas.', '', 'It is cool, so I would like a bowl of hot soup.', array['pinggan','kicap']::text[]),
  ('pinggan', 'Sila letak nasi ayam di atas ＿＿ putih.', '', 'Please put the chicken rice on the white plate.', array['kicap','timun']::text[]),
  ('timun', 'Di sebelah nasi ayam ada beberapa hirisan ＿＿ hijau.', '', 'Next to the chicken rice are a few slices of green cucumber.', array['pinggan','sup']::text[]),
  ('sudu', 'Anda perlukan ＿＿ apabila minum sup.', '', 'You need a spoon when drinking soup.', array['timun','bos']::text[]),
  ('tukang masak', 'Nasi ayam yang dimasak oleh ＿＿ ini sangat wangi.', '', 'The chicken rice this chef cooked smells great.', array['sudu','kicap']::text[]),
  ('teh susu', 'Setiap petang saya minum secawan ＿＿.', '', 'I have a cup of milk tea every afternoon.', array['cawan','penyedut minuman']::text[]),
  ('ais', 'Tolong tambah lebih ＿＿; saya mahu yang sejuk.', '', 'Please add more ice; I want it icy cold.', array['cawan','penyedut minuman']::text[]),
  ('cawan', 'Tolong beri saya ＿＿ yang bersih.', '', 'Please give me a clean cup.', array['gula','ais']::text[]),
  ('gula', 'Kopi saya tanpa ＿＿, ya.', '', 'No sugar in my coffee, please.', array['cawan','penyedut minuman']::text[]),
  ('panas', 'Cuaca sejuk, jadi saya mahu secawan teh ＿＿.', '', 'It is cold, so I would like a cup of hot tea.', array['penyedut minuman','cawan']::text[]),
  ('penyedut minuman', 'Tolong beri saya ＿＿; saya mahu minum air kelapa.', '', 'Please give me a straw; I want to drink coconut water.', array['susu','cawan']::text[]),
  ('susu', 'Kanak-kanak minum segelas ＿＿ setiap pagi.', '', 'Children drink a glass of milk every morning.', array['penyedut minuman','panas']::text[]),
  ('tembikai', '＿＿ sejuk ialah penghilang dahaga terbaik pada musim panas.', '', 'Cold watermelon is the best thirst-quencher in summer.', array['beg plastik','murah']::text[]),
  ('mangga', 'Saya membeli sebiji ＿＿ yang kuning.', '', 'I bought a yellow mango.', array['manis','murah']::text[]),
  ('segar', 'Buah ini sangat ＿＿; baru sampai pagi tadi.', '', 'This fruit is very fresh; it only arrived this morning.', array['tembikai','beg plastik']::text[]),
  ('murah', 'Tiga biji dua dolar sahaja; ＿＿ sungguh!', '', 'Three for only two dollars; so cheap!', array['tembikai','beg plastik']::text[]),
  ('epal', 'Saya makan sebiji ＿＿ merah setiap hari.', '', 'I eat a red apple every day.', array['beg plastik','manis']::text[]),
  ('pisang', 'Monyet paling suka makan ＿＿ yang kuning.', '', 'Monkeys love eating yellow bananas best.', array['beg plastik','murah']::text[]),
  ('manis', 'Mangga ini sangat ＿＿, seperti gula.', '', 'This mango is very sweet, like sugar.', array['beg plastik','epal']::text[]),
  ('beg plastik', 'Tolong beri saya ＿＿ untuk mengisi buah.', '', 'Please give me a bag to put the fruit in.', array['pisang','segar']::text[]),
  ('get tambang', 'Sila letakkan kad anda pada pengesan di ＿＿.', '', 'Please place your card on the sensor of the gate.', array['tiket','kereta api']::text[]),
  ('tiket', 'Saya tiada kad, jadi saya membeli ＿＿.', '', 'I have no card, so I bought a ticket.', array['kelewatan','kereta api']::text[]),
  ('kereta api', '＿＿ akan tiba di stesen sebentar lagi.', '', 'The train is about to arrive at the station.', array['tiket','kelewatan']::text[]),
  ('kelewatan', 'Ada kerosakan isyarat dan kereta api akan mengalami ＿＿ sepuluh minit.', '', 'There is a signal fault; the train will be delayed ten minutes.', array['tiket','get tambang']::text[]),
  ('pengumuman', 'Sila dengar ＿＿; kereta api akan lewat lima minit.', '', 'Please listen to the announcement; the train will be five minutes late.', array['peta','get tambang']::text[]),
  ('arah', 'Anda tersalah ＿＿; pergi ke platform di seberang.', '', 'You took the wrong direction; go to the platform opposite.', array['pengumuman','kelewatan']::text[]),
  ('kecemasan', 'Dalam keadaan ＿＿, sila tekan butang merah.', '', 'In an emergency, please press the red button.', array['tiket','peta']::text[]),
  ('peta', 'Saya tidak faham laluan ini; tolong beri saya ＿＿.', '', 'I cannot understand the route; please give me a map.', array['get tambang','arah']::text[]),
  ('pemegang tangan', 'Bas bergerak laju; sila pegang ＿＿.', '', 'The bus is moving fast; please hold the handrail.', array['loceng','perhentian akhir']::text[]),
  ('loceng', 'Jika mahu turun, sila tekan ＿＿.', '', 'If you want to get off, please press the bell.', array['pemegang tangan','kesesakan lalu lintas']::text[]),
  ('perhentian akhir', '＿＿ bas ini ialah Jurong East.', '', 'The last stop of this bus is Jurong East.', array['loceng','pemegang tangan']::text[]),
  ('kesesakan lalu lintas', 'Apabila hujan, selalu ada ＿＿, jadi bas datang lambat.', '', 'It often jams when it rains, so the bus comes slowly.', array['loceng','perhentian akhir']::text[]),
  ('stereng', 'Pemandu memegang ＿＿ dengan kedua-dua tangan dan memandu dengan berhati-hati.', '', 'The driver holds the steering wheel with both hands and drives carefully.', array['gerabak','perhentian akhir']::text[]),
  ('beri tempat duduk', 'Apabila melihat warga emas naik, anda patut ＿＿.', '', 'When you see an elderly person board, you should offer your seat.', array['gerabak','pemegang tangan']::text[]),
  ('brek', 'Ada orang melintas jalan di hadapan, jadi pemandu terus menekan ＿＿.', '', 'Someone was crossing the road ahead, so the driver braked at once.', array['gerabak','pemegang tangan']::text[]),
  ('gerabak', 'Di dalam ＿＿ ini sangat sesak.', '', 'It is very crowded inside this carriage.', array['brek','beri tempat duduk']::text[]),
  ('lapangan terbang', 'Tolong hantar saya ke ＿＿ Changi.', '', 'Please take me to Changi Airport.', array['alamat','lampu merah']::text[]),
  ('alamat', 'Sila beritahu saya ＿＿ anda.', '', 'Please tell me your address.', array['bagasi','lampu merah']::text[]),
  ('lampu merah', 'Ada ＿＿ di hadapan, jadi kita perlu berhenti.', '', 'There is a red light ahead, so we have to stop.', array['alamat','bagasi']::text[]),
  ('bagasi', '＿＿ anda boleh diletakkan di dalam but kereta.', '', 'Your luggage can go in the boot.', array['lapangan terbang','lampu merah']::text[]),
  ('tali pinggang keledar', 'Sila pakai ＿＿ selepas masuk.', '', 'Please fasten your seat belt after getting in.', array['alamat','bagasi']::text[]),
  ('navigasi', 'Pemandu membuka ＿＿ dan mengikut peta.', '', 'The driver turns on the navigation and follows the map.', array['bagasi','baki wang']::text[]),
  ('baki wang', 'Saya beri pemandu seratus dolar dan dia perlu memulangkan ＿＿.', '', 'I gave the driver a hundred dollars and he has to give me change.', array['membelok','lampu merah']::text[]),
  ('membelok', 'Sila ＿＿ ke kanan di persimpangan di hadapan.', '', 'Please turn right at the junction ahead.', array['tali pinggang keledar','bagasi']::text[]),
  ('karangan', 'Cikgu mahu kami menulis ＿＿ tentang keluarga.', '', 'The teacher wants us to write a composition about family.', array['pensel','papan hitam']::text[]),
  ('tamat kelas', 'Apabila loceng berbunyi, tibalah masa untuk ＿＿.', '', 'When the bell rings, it is time for class to end.', array['buku teks','pensel']::text[]),
  ('tarian', 'Pusat komuniti ada kelas ＿＿ setiap hari Rabu.', '', 'The community centre has a dance class every Wednesday.', array['tolong','selamat datang']::text[]),
  ('notis', 'Sila lihat ＿＿ di dinding; ia menunjukkan waktu aktiviti.', '', 'Please look at the notice on the wall; it shows the activity times.', array['ahli','tolong']::text[]),
  ('nombor', 'Sila catat ＿＿ plat kereta dan beritahu polis.', '', 'Please note down the car plate number and tell the police.', array['dompet','sesat']::text[]),
  ('kad pengenalan', 'Tunjukkan ＿＿ anda; saya perlu memeriksanya.', '', 'Show me your ID; I need to check it.', array['pencuri','sesat']::text[]),
  ('paha ayam', 'Saya mahu nasi ayam dengan ＿＿ tambahan.', '', 'I would like a chicken rice with an extra drumstick.', array['sup','tukang masak']::text[]),
  ('sos cili', 'Orang yang tidak boleh makan pedas jangan tambah ＿＿.', '', 'People who cannot eat spicy food should not add chilli sauce.', array['pinggan','sudu']::text[]),
  ('lemon', 'Teh ＿＿ ais sangat menyegarkan pada musim panas.', '', 'Iced lemon tea is especially refreshing in summer.', array['cawan','penyedut minuman']::text[]),
  ('susu soya', 'Datuk suka secawan ＿＿ panas untuk sarapan.', '', 'Grandpa likes a cup of hot soy milk for breakfast.', array['penyedut minuman','cawan']::text[]),
  ('oren', 'Ibu mengupas sebiji ＿＿ untuk saya makan.', '', 'Mum peeled an orange for me to eat.', array['beg plastik','manis']::text[]),
  ('durian', '＿＿ ada bau yang istimewa; ada yang suka dan ada yang takut.', '', 'Durian has a special smell; some love it and some fear it.', array['beg plastik','murah']::text[]),
  ('tambah nilai', 'Kad saya sudah habis wang, jadi saya perlu ＿＿.', '', 'My card has no money left, so I need to top it up.', array['pengumuman','arah']::text[]),
  ('barang hilang', 'Saya tertinggal payung dalam kereta api; di manakah pejabat ＿＿?', '', 'I left my umbrella on the train; where is the lost property office?', array['get tambang','tiket']::text[]),
  ('tiba di perhentian', 'Perhatian; bas akan segera ＿＿.', '', 'Attention please; the bus is about to arrive at the stop.', array['pemegang tangan','gerabak']::text[]),
  ('duduk dengan tetap', 'Bas sedang bergerak; sila ＿＿ dan pegang pemegang tangan.', '', 'The bus is moving; please sit steady and hold the handrail.', array['gerabak','perhentian akhir']::text[]),
  ('teksi kosong', 'Ada ＿＿ di tepi jalan; mari kita lambai cepat.', '', 'There is a free taxi by the road; let us wave quickly.', array['tali pinggang keledar','navigasi']::text[]),
  ('tempat duduk belakang', 'Kanak-kanak mesti duduk di ＿＿ dan memakai tali pinggang keledar.', '', 'Children must sit in the back seat and fasten the seat belt.', array['navigasi','baki wang']::text[]),
  ('வகுப்பறை', 'மாணவர்கள் எல்லோரும் ＿＿யில் அமர்ந்து ஆசிரியரின் கதையைக் கேட்கிறார்கள்.', '', 'The pupils all sit in the classroom to hear the teacher''s story.', array['வீட்டுப்பாடம்','பள்ளிப் பை']::text[]),
  ('வீட்டுப்பாடம்', 'வீடு திரும்பியதும் விளையாடுவதற்கு முன் நான் ＿＿ செய்வேன்.', '', 'After getting home I do my homework before playing.', array['வகுப்பறை','பள்ளிப் பை']::text[]),
  ('பள்ளிப் பை', 'அவனுடைய ＿＿யில் பாடப்புத்தகங்களும் பென்சில்களும் உள்ளன.', '', 'His school bag has textbooks and pencils in it.', array['வீட்டுப்பாடம்','தேர்வு']::text[]),
  ('சக மாணவர்', 'வகுப்பு முடிந்த பிறகு நான் என் ＿＿களுடன் விளையாடுவேன்.', '', 'After class I play with my classmates.', array['வீட்டுப்பாடம்','பள்ளிப் பை']::text[]),
  ('தேர்வு', 'நாளை கணிதத் ＿＿ இருக்கிறது, அதனால் இன்றிரவு நான் படிக்க வேண்டும்.', '', 'There is a maths exam tomorrow, so I must revise tonight.', array['கரும்பலகை','பென்சில்']::text[]),
  ('பாடப்புத்தகம்', 'உங்கள் ＿＿ பத்தாம் பக்கத்தைத் திருப்புங்கள்.', '', 'Please turn your textbook to page ten.', array['தேர்வு','வகுப்பறை']::text[]),
  ('பென்சில்', 'நான் ＿＿ கொண்டு எழுதுகிறேன், தவறானால் அழித்துவிடலாம்.', '', 'I write with a pencil, so I can rub out mistakes.', array['கரும்பலகை','வீட்டுப்பாடம்']::text[]),
  ('கரும்பலகை', 'ஆசிரியர் இன்றைய தலைப்பை ＿＿யில் எழுதினார்.', '', 'The teacher wrote today''s topic on the blackboard.', array['சக மாணவர்','தேர்வு']::text[]),
  ('தன்னார்வலர்', 'நான் சமூக மன்றத்தின் ＿＿; ஒவ்வொரு சனிக்கிழமையும் உதவுகிறேன்.', '', 'I am a volunteer at the community centre and help out every Saturday.', array['பதிவு செய்','பாடநெறி']::text[]),
  ('பதிவு செய்', 'கையெழுத்துக் கலை வகுப்பில் சேர விரும்பினால், முன்மேசையில் ＿＿யுங்கள்.', '', 'If you want to join the calligraphy class, please sign up at the front desk.', array['வரவேற்பு','தன்னார்வலர்']::text[]),
  ('பாடநெறி', 'இந்த ＿＿ முதியவர்களுக்குத் தொலைபேசி பயன்படுத்தக் கற்றுக்கொடுக்கிறது.', '', 'This course teaches the elderly how to use a phone.', array['பதிவு செய்','வரவேற்பு']::text[]),
  ('வரவேற்பு', 'அந்த அம்மா சிரித்துக்கொண்டே, “எங்கள் மன்றத்திற்கு ＿＿!” என்றார்.', '', 'The auntie smiled and said, “Welcome to our club!”', array['பாடநெறி','தன்னார்வலர்']::text[]),
  ('கையெழுத்துக் கலை', 'ஒவ்வொரு சனிக்கிழமையும் தாத்தா மன்றத்தில் ＿＿ பயிற்சி செய்யச் செல்வார்.', '', 'Every Saturday Grandpa goes to the club to practise calligraphy.', array['தன்னார்வலர்','வரவேற்பு']::text[]),
  ('இலவசம்', 'இந்தச் சொற்பொழிவு ＿＿; பணம் செலுத்தத் தேவையில்லை.', '', 'This talk is free; you do not need to pay.', array['உதவி','கையெழுத்துக் கலை']::text[]),
  ('உதவி', 'அண்டை வீட்டார் வீடு மாறுகிறார்கள், அதனால் பெட்டிகளைத் தூக்க நாங்கள் ＿＿ செய்யப் போகிறோம்.', '', 'The neighbour is moving house, so we go to help carry boxes.', array['இலவசம்','உறுப்பினர்']::text[]),
  ('உறுப்பினர்', 'அவர் மன்றத்தின் ＿＿; எல்லா நிகழ்ச்சிகளிலும் பங்கேற்கலாம்.', '', 'He is a member of the club and can join all the activities.', array['பாடநெறி','உதவி']::text[]),
  ('காவல்துறை', 'வழி தவறியவர்கள் ＿＿யிடம் உதவி கேட்கலாம்.', '', 'People who are lost can ask the police for help.', array['பாதுகாப்பு','ரோந்து']::text[]),
  ('பாதுகாப்பு', 'இரவில் வீடு திரும்பும்போது கவனமாக இருங்கள்; உங்கள் ＿＿ முக்கியம்.', '', 'Be careful going home at night and mind your safety.', array['காவல்துறை','போலீசுக்குத் தெரிவி']::text[]),
  ('ரோந்து', 'காவல்துறை ஒவ்வொரு இரவும் அக்கம்பக்கத்தில் ＿＿ செல்கிறது.', '', 'The police patrol the neighbourhood every night.', array['பாதுகாப்பு','போலீசுக்குத் தெரிவி']::text[]),
  ('போலீசுக்குத் தெரிவி', 'சந்தேகமான ஆளைப் பார்த்தால் உடனே ＿＿யுங்கள்.', '', 'If you see a suspicious person, call the police at once.', array['ரோந்து','பாதுகாப்பு']::text[]),
  ('வழி தவறி', 'சிறு குழந்தை கடைத்தொகுதியில் ＿＿ அழத் தொடங்கியது.', '', 'The little child got lost in the mall and began to cry.', array['பணப்பை','திருடன்']::text[]),
  ('திருடன்', 'காவல்துறையினர் பிடித்தவன் பொருட்களைத் திருடிய ＿＿.', '', 'The police caught the thief who stole things.', array['வழி தவறி','நினைவூட்டு']::text[]),
  ('பணப்பை', 'என் ＿＿ காணவில்லை; அதில் என் அடையாள அட்டை இருக்கிறது.', '', 'My wallet is missing and my ID card is inside.', array['திருடன்','நினைவூட்டு']::text[]),
  ('நினைவூட்டு', 'கதவுகளையும் ஜன்னல்களையும் பூட்டுமாறு காவல்துறை எல்லோருக்கும் ＿＿கிறது.', '', 'The police remind everyone to lock their doors and windows.', array['பணப்பை','வழி தவறி']::text[]),
  ('முதலாளி', '＿＿, இன்னொரு கிண்ணம் சூப் கொடுங்கள்!', '', 'Boss, another bowl of soup please!', array['சாதம்','சோயா சாஸ்']::text[]),
  ('சாதம்', 'இந்தக் கோழிக்கு மணமுள்ள ＿＿ தான் சிறந்த ஜோடி.', '', 'This chicken is best with fragrant rice.', array['சோயா சாஸ்','சூப்']::text[]),
  ('சோயா சாஸ்', 'சாதத்தின் மேல் கொஞ்சம் ＿＿ ஊற்றுங்கள்.', '', 'Please drizzle a little soy sauce on the rice.', array['சூப்','முதலாளி']::text[]),
  ('சூப்', 'குளிராக இருக்கிறது, அதனால் எனக்கு ஒரு கிண்ணம் சூடான ＿＿ வேண்டும்.', '', 'It is cool, so I would like a bowl of hot soup.', array['சாதம்','சோயா சாஸ்']::text[]),
  ('தட்டு', 'கோழி சாதத்தை வெள்ளை ＿＿ ஒன்றில் வையுங்கள்.', '', 'Please put the chicken rice on the white plate.', array['சோயா சாஸ்','வெள்ளரிக்காய்']::text[]),
  ('வெள்ளரிக்காய்', 'கோழி சாதத்தின் பக்கத்தில் சில பச்சை ＿＿ துண்டுகள் உள்ளன.', '', 'Next to the chicken rice are a few slices of green cucumber.', array['தட்டு','சூப்']::text[]),
  ('கரண்டி', 'சூப் குடிக்க ＿＿ தேவை.', '', 'You need a spoon when drinking soup.', array['வெள்ளரிக்காய்','முதலாளி']::text[]),
  ('சமையல்காரர்', 'இந்த ＿＿ சமைத்த கோழி சாதம் மிக மணமாக இருக்கிறது.', '', 'The chicken rice this chef cooked smells great.', array['கரண்டி','சாதம்']::text[]),
  ('பால் தேநீர்', 'ஒவ்வொரு மதியமும் நான் ஒரு கப் ＿＿ குடிப்பேன்.', '', 'I have a cup of milk tea every afternoon.', array['குவளை','ஸ்ட்ரா']::text[]),
  ('காபி', 'காலையில் விழித்திருக்க அப்பாவுக்கு ＿＿ வேண்டும்.', '', 'Dad needs coffee in the morning to feel awake.', array['குவளை','ஸ்ட்ரா']::text[]),
  ('ஐஸ்', 'இன்னும் கொஞ்சம் ＿＿ போடுங்கள்; எனக்கு ஜில்லென்று வேண்டும்.', '', 'Please add more ice; I want it icy cold.', array['குவளை','ஸ்ட்ரா']::text[]),
  ('குவளை', 'எனக்கு ஒரு சுத்தமான ＿＿ கொடுங்கள்.', '', 'Please give me a clean cup.', array['சர்க்கரை','ஐஸ்']::text[]),
  ('சர்க்கரை', 'என் காபியில் ＿＿ வேண்டாம்.', '', 'No sugar in my coffee, please.', array['குவளை','ஸ்ட்ரா']::text[]),
  ('சூடான', 'குளிராக இருக்கிறது, அதனால் எனக்கு ஒரு கப் ＿＿ தேநீர் வேண்டும்.', '', 'It is cold, so I would like a cup of hot tea.', array['ஸ்ட்ரா','குவளை']::text[]),
  ('ஸ்ட்ரா', 'எனக்கு ஒரு ＿＿ கொடுங்கள்; நான் இளநீர் குடிக்க விரும்புகிறேன்.', '', 'Please give me a straw; I want to drink coconut water.', array['பால்','குவளை']::text[]),
  ('பால்', 'குழந்தைகள் ஒவ்வொரு காலையும் ஒரு குவளை ＿＿ குடிக்கிறார்கள்.', '', 'Children drink a glass of milk every morning.', array['ஸ்ட்ரா','சூடான']::text[]),
  ('தர்பூசணி', 'கோடையில் தாகத்தைத் தணிக்கக் குளிர்ந்த ＿＿ தான் சிறந்தது.', '', 'Cold watermelon is the best thirst-quencher in summer.', array['பை','மலிவு']::text[]),
  ('மாம்பழம்', 'நான் ஒரு மஞ்சள் ＿＿ வாங்கினேன்.', '', 'I bought a yellow mango.', array['இனிப்பு','மலிவு']::text[]),
  ('புதியது', 'இந்தப் பழம் மிகவும் ＿＿; இன்று காலைதான் வந்தது.', '', 'This fruit is very fresh; it only arrived this morning.', array['தர்பூசணி','பை']::text[]),
  ('மலிவு', 'மூன்று பழம் இரண்டு டாலர் மட்டுமே; எவ்வளவு ＿＿!', '', 'Three for only two dollars; so cheap!', array['தர்பூசணி','பை']::text[]),
  ('ஆப்பிள்', 'நான் தினமும் ஒரு சிவப்பு ＿＿ சாப்பிடுகிறேன்.', '', 'I eat a red apple every day.', array['பை','இனிப்பு']::text[]),
  ('வாழைப்பழம்', 'குரங்குகளுக்கு மஞ்சள் ＿＿ சாப்பிடத்தான் மிகவும் பிடிக்கும்.', '', 'Monkeys love eating yellow bananas best.', array['பை','மலிவு']::text[]),
  ('இனிப்பு', 'இந்த மாம்பழம் சர்க்கரை போல ＿＿.', '', 'This mango is very sweet, like sugar.', array['பை','ஆப்பிள்']::text[]),
  ('பை', 'பழங்களைப் போட எனக்கு ஒரு ＿＿ கொடுங்கள்.', '', 'Please give me a bag to put the fruit in.', array['வாழைப்பழம்','புதியது']::text[]),
  ('நுழைவு வாயில்', 'உங்கள் அட்டையை ＿＿ உள்ள உணர்கருவியில் வையுங்கள்.', '', 'Please place your card on the sensor of the gate.', array['பயணச்சீட்டு','வரைபடம்']::text[]),
  ('பயணச்சீட்டு', 'என்னிடம் அட்டை இல்லை, அதனால் ஒரு ＿＿ வாங்கினேன்.', '', 'I have no card, so I bought a ticket.', array['அவசரம்','வரைபடம்']::text[]),
  ('ஒலிபெருக்கி அறிவிப்பு', '＿＿ கவனமாகக் கேளுங்கள்; ரயில் ஐந்து நிமிடம் தாமதமாக வரும்.', '', 'Please listen to the announcement; the train will be five minutes late.', array['வரைபடம்','நுழைவு வாயில்']::text[]),
  ('திசை', 'நீங்கள் தவறான ＿＿ வந்துவிட்டீர்கள்; எதிர்ப்புறம் உள்ள நடைமேடைக்குச் செல்லுங்கள்.', '', 'You took the wrong direction; go to the platform opposite.', array['ஒலிபெருக்கி அறிவிப்பு','அவசரம்']::text[]),
  ('அவசரம்', '＿＿ என்றால் சிவப்புப் பொத்தானை அழுத்துங்கள்.', '', 'In an emergency, please press the red button.', array['பயணச்சீட்டு','வரைபடம்']::text[]),
  ('வரைபடம்', 'வழி எனக்குப் புரியவில்லை; எனக்கு ஒரு ＿＿ கொடுங்கள்.', '', 'I cannot understand the route; please give me a map.', array['நுழைவு வாயில்','திசை']::text[]),
  ('கைப்பிடி', 'பேருந்து வேகமாகப் போகிறது; ＿＿ பிடித்துக்கொள்ளுங்கள்.', '', 'The bus is moving fast; please hold the handrail.', array['மணி','கடைசி நிறுத்தம்']::text[]),
  ('மணி', 'இறங்க வேண்டுமானால் ＿＿ அழுத்துங்கள்.', '', 'If you want to get off, please press the bell.', array['கைப்பிடி','போக்குவரத்து நெரிசல்']::text[]),
  ('கடைசி நிறுத்தம்', 'இந்தப் பேருந்தின் ＿＿ ஜூரோங் ஈஸ்ட்.', '', 'The last stop of this bus is Jurong East.', array['மணி','கைப்பிடி']::text[]),
  ('போக்குவரத்து நெரிசல்', 'மழை பெய்தால் அடிக்கடி ＿＿ ஏற்படும், அதனால் பேருந்து மெதுவாக வரும்.', '', 'It often jams when it rains, so the bus comes slowly.', array['மணி','கடைசி நிறுத்தம்']::text[]),
  ('ஸ்டீயரிங்', 'ஓட்டுநர் இரு கைகளாலும் ＿＿ பிடித்து கவனமாக ஓட்டுகிறார்.', '', 'The driver holds the steering wheel with both hands and drives carefully.', array['பெட்டி','கடைசி நிறுத்தம்']::text[]),
  ('இருக்கை கொடு', 'முதியவர் ஏறுவதைப் பார்த்தால் நீங்கள் ＿＿க்க வேண்டும்.', '', 'When you see an elderly person board, you should offer your seat.', array['பெட்டி','கைப்பிடி']::text[]),
  ('பிரேக்', 'முன்னால் ஒருவர் சாலையைக் கடந்தார்; ஓட்டுநர் உடனே ＿＿ போட்டார்.', '', 'Someone was crossing the road ahead, so the driver braked at once.', array['பெட்டி','கைப்பிடி']::text[]),
  ('பெட்டி', 'இந்த ＿＿ உள்ளே மிகவும் நெரிசலாக இருக்கிறது.', '', 'It is very crowded inside this carriage.', array['பிரேக்','இருக்கை கொடு']::text[]),
  ('விமான நிலையம்', 'எனக்கு சாங்கி ＿＿ போக வேண்டும்.', '', 'Please take me to Changi Airport.', array['முகவரி','சிவப்பு விளக்கு']::text[]),
  ('முகவரி', 'உங்கள் ＿＿ சொல்லுங்கள்.', '', 'Please tell me your address.', array['சாமான்','சிவப்பு விளக்கு']::text[]),
  ('சிவப்பு விளக்கு', 'முன்னால் ＿＿ எரிகிறது, அதனால் நிற்க வேண்டும்.', '', 'There is a red light ahead, so we have to stop.', array['முகவரி','சாமான்']::text[]),
  ('சாமான்', 'உங்கள் ＿＿ காரின் பின்பெட்டியில் வைக்கலாம்.', '', 'Your luggage can go in the boot.', array['விமான நிலையம்','சிவப்பு விளக்கு']::text[]),
  ('இருக்கைப் பட்டை', 'ஏறியதும் உங்கள் ＿＿ அணிந்து கொள்ளுங்கள்.', '', 'Please fasten your seat belt after getting in.', array['முகவரி','சாமான்']::text[]),
  ('வழிசெலுத்தல்', 'ஓட்டுநர் ＿＿ போட்டு வரைபடத்தைப் பின்பற்றுகிறார்.', '', 'The driver turns on the navigation and follows the map.', array['சாமான்','மீதிப் பணம்']::text[]),
  ('மீதிப் பணம்', 'நான் ஓட்டுநருக்கு நூறு டாலர் கொடுத்தேன்; அவர் ＿＿ தர வேண்டும்.', '', 'I gave the driver a hundred dollars and he has to give me change.', array['திரும்பு','சிவப்பு விளக்கு']::text[]),
  ('திரும்பு', 'முன்னால் உள்ள சந்திப்பில் வலப்புறம் ＿＿ங்கள்.', '', 'Please turn right at the junction ahead.', array['இருக்கைப் பட்டை','சாமான்']::text[]),
  ('கட்டுரை', 'ஆசிரியர் எங்களைக் குடும்பத்தைப் பற்றி ＿＿ எழுதச் சொன்னார்.', '', 'The teacher wants us to write a composition about family.', array['பென்சில்','கரும்பலகை']::text[]),
  ('வகுப்பு முடிவு', 'மணி அடித்ததும் ＿＿ ஆகும்.', '', 'When the bell rings, it is time for class to end.', array['பாடப்புத்தகம்','பென்சில்']::text[]),
  ('நடனம்', 'சமூக மன்றத்தில் ஒவ்வொரு புதன்கிழமையும் ＿＿ வகுப்பு உண்டு.', '', 'The community centre has a dance class every Wednesday.', array['உதவி','வரவேற்பு']::text[]),
  ('அறிவிப்பு', 'சுவரில் இருக்கும் ＿＿ பார்க்கவும்; அதில் நிகழ்ச்சி நேரங்கள் உள்ளன.', '', 'Please look at the notice on the wall; it shows the activity times.', array['உறுப்பினர்','உதவி']::text[]),
  ('எண்', 'காரின் பதிவு ＿＿ எழுதிக்கொண்டு போலீசிடம் சொல்லுங்கள்.', '', 'Please note down the car plate number and tell the police.', array['பணப்பை','வழி தவறி']::text[]),
  ('அடையாள அட்டை', 'உங்கள் ＿＿ காட்டுங்கள்; நான் சரிபார்க்க வேண்டும்.', '', 'Show me your ID; I need to check it.', array['திருடன்','வழி தவறி']::text[]),
  ('கோழிக்கால்', 'ஒரு கோழி சாதம் கொடுங்கள்; கூடுதலாக ஒரு ＿＿ வேண்டும்.', '', 'I would like a chicken rice with an extra drumstick.', array['சூப்','சமையல்காரர்']::text[]),
  ('மிளகாய் சாஸ்', 'காரம் சாப்பிட முடியாதவர்கள் ＿＿ சேர்க்கக் கூடாது.', '', 'People who cannot eat spicy food should not add chilli sauce.', array['தட்டு','கரண்டி']::text[]),
  ('எலுமிச்சை', 'கோடையில் ஐஸ் ＿＿ தேநீர் மிகவும் புத்துணர்ச்சி தரும்.', '', 'Iced lemon tea is especially refreshing in summer.', array['குவளை','ஸ்ட்ரா']::text[]),
  ('சோயா பால்', 'தாத்தாவுக்கு காலை உணவுக்கு ஒரு கப் சூடான ＿＿ பிடிக்கும்.', '', 'Grandpa likes a cup of hot soy milk for breakfast.', array['ஸ்ட்ரா','குவளை']::text[]),
  ('ஆரஞ்சு', 'அம்மா எனக்காக ஒரு ＿＿ உரித்துக் கொடுத்தார்.', '', 'Mum peeled an orange for me to eat.', array['பை','இனிப்பு']::text[]),
  ('துரியன்', '＿＿ பழத்துக்கு ஒரு தனி வாசனை உண்டு; சிலருக்குப் பிடிக்கும், சிலர் பயப்படுவார்கள்.', '', 'Durian has a special smell; some love it and some fear it.', array['பை','மலிவு']::text[]),
  ('பணம் சேர்', 'என் அட்டையில் பணம் இல்லை, அதனால் நான் ＿＿க்க வேண்டும்.', '', 'My card has no money left, so I need to top it up.', array['ஒலிபெருக்கி அறிவிப்பு','திசை']::text[]),
  ('தொலைந்த பொருள்', 'நான் ரயிலில் குடையை விட்டுவிட்டேன்; ＿＿ அலுவலகம் எங்கே?', '', 'I left my umbrella on the train; where is the lost property office?', array['நுழைவு வாயில்','பயணச்சீட்டு']::text[]),
  ('நிறுத்தம் வரப்போகிறது', 'கவனியுங்கள்; அடுத்த ＿＿.', '', 'Attention please; the bus is about to arrive at the stop.', array['கைப்பிடி','பெட்டி']::text[]),
  ('நிலையாக உட்கார்', 'பேருந்து நகர்கிறது; ＿＿ந்து கைப்பிடியைப் பிடித்துக்கொள்ளுங்கள்.', '', 'The bus is moving; please sit steady and hold the handrail.', array['பெட்டி','கடைசி நிறுத்தம்']::text[]),
  ('காலி டாக்ஸி', 'சாலையோரம் ஒரு ＿＿ இருக்கிறது; சீக்கிரம் கை காட்டுவோம்.', '', 'There is a free taxi by the road; let us wave quickly.', array['இருக்கைப் பட்டை','வழிசெலுத்தல்']::text[]),
  ('பின் இருக்கை', 'குழந்தைகள் ＿＿யில் உட்கார்ந்து இருக்கைப் பட்டை அணிய வேண்டும்.', '', 'Children must sit in the back seat and fasten the seat belt.', array['வழிசெலுத்தல்','மீதிப் பணம்']::text[])
